import Foundation

/// `-RCDevWebMFault <spec>`, a dev-only launch default (dev tools only; codec-export C3 fix
/// pass 1, spec §11 CX-15 (6)): one fault put into every `av1_webm` export of the launch, so
/// a proof can show that a stop on either pump ends the export — each pump reads its own
/// `AVAssetReader`, so neither read can be starved by the other's stop (G-17).
///
///   `audio@N`       the audio pump fails at its Nth read, before it
///   `video@N`       the video sink fails at its Nth packet
///   `audio-hold@N`  the audio pump waits `holdSeconds` at its Nth read, before it, without
///                   looking at the stop flag — a read that is slow to return — then reads
///
/// Each firing is one log line, `framejob webm dev fault: …`, and with a fault set the
/// writer logs its readers' states once both pumps have left (`framejob webm dev readers:
/// video S, audio S`, with ` (one reader)` should the two ever be one object). Neither
/// carries the parity check's prefix. Nil in a build without dev tools.
final class ExportWebMDevFault {
    static let key = "RCDevWebMFault"
    static let holdSeconds = 3.0

    enum Kind: String { case audio, video, audioHold = "audio-hold" }

    let kind: Kind
    let at: Int

    private init(kind: Kind, at: Int) {
        self.kind = kind
        self.at = at
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ExportWebMDevFault does not support NSCoder")
    }

    /// The launch's fault, or nil (none set, malformed, or no dev tools).
    static func current() -> ExportWebMDevFault? {
        #if FRAMEJOB_DEV_TOOLS
        guard let spec = UserDefaults.standard.string(forKey: key) else { return nil }
        let parts = spec.split(separator: "@", maxSplits: 1).map(String.init)
        guard parts.count == 2, let kind = Kind(rawValue: parts[0]), let at = Int(parts[1]),
            at > 0
        else { return nil }
        return ExportWebMDevFault(kind: kind, at: at)
        #else
        return nil
        #endif
    }

    /// The audio pump, before its read number `read` (from 1): throws at `audio@N`, waits at
    /// `audio-hold@N`.
    func beforeAudioRead(_ read: Int) throws {
        guard read == at else { return }
        switch kind {
        case .audio:
            Self.log("fault: the audio pump fails at read \(read)")
            throw Exporter.ExportError.failed("A dev fault stopped the audio at read \(read).")
        case .audioHold:
            Self.log("fault: the audio read \(read) is held \(Self.holdSeconds) s")
            Thread.sleep(forTimeInterval: Self.holdSeconds)
            Self.log("fault: the audio read \(read) goes on")
        case .video:
            return
        }
    }

    /// The video sink, at its packet number `packet` (from 1): the failure at `video@N`.
    func videoPacket(_ packet: Int) -> (any Error)? {
        guard kind == .video, packet == at else { return nil }
        Self.log("fault: the video sink fails at packet \(packet)")
        return Exporter.ExportError.failed("A dev fault stopped the video at packet \(packet).")
    }

    static func log(_ line: String) {
        NSLog("framejob webm dev %@", line)
    }
}

import AVFoundation

// MARK: - The writer pipeline

/// Reads the composed movie back out of AVFoundation and writes it to a file:
/// the `AVAssetWriter` half of `Exporter` (spec §7.8).
///
/// **One movie, one description of it.** The reader is built over the SAME
/// `AVComposition`, the SAME `AVVideoComposition` and the SAME `AVAudioMix`
/// that `Playback` plays and `Exporter.renderFrame` samples — the custom
/// `Compositor` runs here exactly as it does on screen, from the same frame
/// recipes, through the same `RecipeSource` slot, and so do the audio mix's
/// processing taps (`addAudioOutput`). Nothing in this file draws a pixel;
/// beyond the alpha rows' straightening (below), it moves what AVFoundation
/// composed into an encoder and adds the three things a preset name cannot
/// express: a chapter track, explicit bitrates, and an output size the sheet
/// actually promised.
///
/// **The two samples it touches** are made here because this is where the
/// export's samples exist, and both are export-only by definition. One is
/// the loudness normalisation's gain: the preview and the file still share
/// one description of the sound (the mix, the ramps and the taps) and differ
/// only by a number the export was asked for. `Exporter` measured that
/// number a moment earlier from a float read of the mix; a gained export
/// reads the same float mix and `ExportAudioGain` multiplies and quantises it
/// once to the 16-bit format every encoder here takes (spec §11 #86). An
/// export with no gain reads the 16-bit decode it always read. The other is
/// the alpha movie rows' picture (`prores_4444`, `hevc_alpha`): the
/// compositor's premultiplied frame is un-premultiplied, its transparent
/// pixels' colour filled from the nearest visible one, and labelled
/// straight (`ExportStraightAlpha`, spec §11 G-35); `h264`'s, `hevc`'s and
/// `hevc_alpha`'s are first rounded to 8 bits (`ExportFrames`, PR-3), and
/// every other row's frame goes to the encoder as the compositor drew it.
///
/// **Why the read is a reader and not a second render.** The alternative —
/// driving the compositor by hand over an `AVAssetImageGenerator`, one frame
/// at a time — is a second rendering path with its own timing, and the whole
/// design exists so there is not one. `AVAssetReaderVideoCompositionOutput`
/// runs the video composition on AVFoundation's own schedule and hands back
/// the very buffers the compositor filled.
///
/// **Times are rebased, not mapped.** The reader's range starts at
/// `settings.start`; every sample is re-timed by subtracting it and the
/// writing session starts at zero, so an in/out export is a file that begins
/// at 00:00 like the session path's did. Letting `startSession(atSourceTime:)`
/// do the mapping instead would leave the container's edit list to decide,
/// which players disagree about.
///
/// **Cancellation and progress.** Every sample checks the flag, so a cancel
/// lands within one frame, and the reader is torn down only once every pump
/// has left its loop (`cancel`); `AVAssetWriter` has no `progress` of its own, so
/// the fraction is kept here from the presentation time of the last sample
/// appended and `Exporter`'s 0.1 s timer reads it.
final class ExportWriter {

    /// The composition, held for the whole write. Not merely tidiness: the
    /// compositor asks `RecipeSource` for a recipe per frame, and the
    /// instructions inside this object carry the key it asks under.
    private let built: BuiltComposition
    private let destination: URL
    /// The slice of the composition being written, in composition time.
    let range: CMTimeRange
    /// `range.duration` in seconds, or 0 for a degenerate range — the
    /// denominator of `progress`.
    private let totalSeconds: Double

    private let reader: AVAssetReader
    let writer: AVAssetWriter
    private var videoOutput: AVAssetReaderOutput?
    var videoInput: AVAssetWriterInput?
    private var audioOutput: AVAssetReaderOutput?
    var audioInput: AVAssetWriterInput?
    var chapterInput: AVAssetWriterInput?
    var chapterSamples: [CMSampleBuffer] = []

    /// One serial queue per input, as `requestMediaDataWhenReady` requires.
    /// Separate queues rather than one shared serial queue: the audio pump
    /// must not sit behind a 4K frame being appended.
    private let videoQueue = DispatchQueue(
        label: "com.kgalligan.framejob.export.video", qos: .userInitiated)
    private let audioQueue = DispatchQueue(
        label: "com.kgalligan.framejob.export.audio", qos: .userInitiated)
    private let chapterQueue = DispatchQueue(
        label: "com.kgalligan.framejob.export.chapters", qos: .userInitiated)

    /// Guards everything the pumps and the main thread both touch.
    private let lock = NSLock()
    private var progressValue: Double = 0
    private var cancelRequested = false
    private var failure: (any Error)?

    /// Called once, on the main thread, and then dropped.
    private var completion: ((Result<URL, any Error>) -> Void)?

    /// The loudness normalisation's gain, or nil when there is none — and
    /// nil is not a multiply by one: the audio is then read as the 16-bit
    /// decode and `pump` never enters the gain path, so an export that was
    /// not normalised is byte-identical to one from before this file knew
    /// what loudness was, by construction rather than by argument.
    ///
    /// Written once, on the main thread, between `init` and `start`; read
    /// by `start` and then only on `audioQueue`. Not under the lock for that
    /// reason and no other.
    private var audioGain: ExportAudioGain?

    /// What the video pump makes of each frame (spec §11 G-35, PR-3;
    /// `frameForm`), set once by `addVideo` in `init` and read only by
    /// `start`; nil hands each frame on as drawn.
    private var frames: ExportFrames?

    /// The encoder row's video pump (`settings.writer`, spec §11 CX-12), set by `addVideo`;
    /// nil on every row AVFoundation encodes.
    private var encodePump: ExportEncodePump?

    /// The audio pump's `end`: the sound cut at the range, padded to it (#337).
    private let audioEnd: ExportAudioEnd

    /// Builds the reader, the writer and every track, or throws the
    /// `Exporter.ExportError` the sheet should show. Nothing is read or
    /// written until `start`.
    init(
        built: BuiltComposition, settings: ExportSettings, chapters: [ExportChapter], to url: URL
    ) throws {
        guard let fileType = Exporter.fileType(for: settings) else {
            throw Exporter.ExportError.fileTypeUnsupported(settings.container)
        }
        self.built = built
        self.destination = url
        self.range = Exporter.timeRange(settings, composition: built.composition)
        self.totalSeconds = max(0, CMTimeGetSeconds(range.duration))
        self.audioEnd = ExportAudioEnd(range: range)

        do {
            reader = try AVAssetReader(asset: built.composition)
            writer = try AVAssetWriter(outputURL: url, fileType: fileType)
        } catch {
            throw Exporter.ExportError.failed(error.localizedDescription)
        }
        reader.timeRange = range
        writer.shouldOptimizeForNetworkUse = settings.optimizeForNetwork

        try addVideo(settings: settings)
        try addAudio(settings: settings)
        addChapters(chapters, settings: settings)
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ExportWriter does not support NSCoder")
    }

    /// Multiplies every audio sample by `gain` on the way to the encoder —
    /// the second half of a loudness-normalised export (`Exporter`'s
    /// measurement pass is the first).
    ///
    /// Main thread, after `init` and before `start`: the gain is the
    /// measurement's answer, and the measurement runs on the build queue
    /// while this object is being constructed. `Exporter.startWriting` is
    /// the one caller.
    ///
    /// A non-finite or non-positive gain is ignored rather than obeyed. A
    /// gain is a number derived from a measurement, and a measurement of
    /// digital silence is −∞; multiplying a file by that would be a silent
    /// export reported as a success. A gain of exactly 1 is ignored too, so
    /// it keeps the un-normalised read.
    func normalizeAudio(byLinearGain gain: Float) {
        guard gain.isFinite, gain > 0, gain != 1 else { return }
        audioGain = ExportAudioGain(linearGain: gain)
    }

    // MARK: - Tracks

    /// The video half: the composition's video tracks through the video
    /// composition, into one encoder input.
    ///
    /// An audio-only preset gets NO video at all, for the reason the session
    /// path gives: attaching the video composition asks the custom compositor
    /// to render frames nothing will write.
    private func addVideo(settings: ExportSettings) throws {
        guard !settings.isAudioOnly else { return }
        let tracks = built.composition.tracks(withMediaType: .video)
        // CompositionBuilder gives a text-and-shapes-only timeline a
        // placeholder track precisely so this is never empty; if it still is,
        // the bundled resource is missing and there is nothing to compose
        // against.
        guard !tracks.isEmpty else { throw Exporter.ExportError.emptyTimeline }
        let canvas = built.videoComposition.renderSize
        try Self.checkAlphaSurvivesTheSize(settings, canvas: canvas)
        let output = Self.videoReadOutput(built, settings: settings)
        guard reader.canAdd(output) else {
            throw Exporter.ExportError.failed(
                "The composition could not be read for export.")
        }
        reader.add(output)

        // An encoder row's packets go in as they are (`ExportEncodePump`).
        let pump = settings.writer == ExportEncodePump.writer
            ? try ExportEncodePump(settings: settings, canvas: canvas, range: range) : nil
        let input = try pump.map {
            AVAssetWriterInput(
                mediaType: .video, outputSettings: nil, sourceFormatHint: $0.formatDescription)
        } ?? AVAssetWriterInput(
            mediaType: .video, outputSettings: try Self.videoSettings(settings, canvas: canvas))
        input.expectsMediaDataInRealTime = false
        guard writer.canAdd(input) else {
            throw Exporter.ExportError.presetUnavailable(Self.presetName(settings))
        }
        writer.add(input)
        videoOutput = output
        videoInput = input
        encodePump = pump
        frames = Self.frameForm(settings).map { ExportFrames(form: $0) }
    }

    /// The audio half: every composition audio track through the plan's mix.
    ///
    /// **`addAudioOutput`'s `audioMix` line is where the preview and the file
    /// agree about sound.**
    /// The mix carries the plan's volume envelope AND, for any track whose
    /// clips use pan, the compressor or noise reduction, the
    /// `MTAudioProcessingTap` that runs them (`AudioTap.swift`). Those taps
    /// were long believed to be an AVPlayer-only feature — true of the
    /// `AVAssetExportSession` this pipeline replaced, and the reason the
    /// effects were left unimplemented — but measured against
    /// `AVAssetReaderAudioMixOutput` they run here as well: a tap that
    /// silenced its buffers produced a silent file, one tap per track saw only
    /// its own track, and with `reader.timeRange` set for an in/out export the
    /// tap is handed COMPOSITION time, so a clip's settings still line up with
    /// the clip. Nothing had to be re-implemented for the export; the DSP has
    /// one implementation and this reads through it.
    ///
    /// The one thing the file and the preview do not share is the reducer's
    /// 512-sample delay on a track that uses it, which both paths have and
    /// neither compensates: 10.7 ms of audio lag at 48 kHz, well inside every
    /// A/V sync tolerance, on tracks the user asked to clean.
    ///
    /// A timeline with no audio at all is not an error — it is a silent
    /// movie, and the track is simply not added. It IS an error when the
    /// preset writes nothing else.
    ///
    /// This adds the writer INPUT only. The reader output is added by `start`
    /// (`addAudioOutput`), because its format depends on the gain, which
    /// arrives after `init`.
    private func addAudio(settings: ExportSettings) throws {
        let tracks = built.composition.tracks(withMediaType: .audio)
        guard !tracks.isEmpty else {
            if settings.isAudioOnly { throw Exporter.ExportError.emptyTimeline }
            return
        }
        let input = AVAssetWriterInput(
            mediaType: .audio, outputSettings: Self.audioSettings(settings))
        input.expectsMediaDataInRealTime = false
        guard writer.canAdd(input) else {
            throw Exporter.ExportError.presetUnavailable(Self.presetName(settings))
        }
        writer.add(input)
        audioInput = input
    }

    /// The mix's reader output (`audioReadOutput`). False when the reader
    /// refuses it; there is no 16-bit fallback for a gained export, because
    /// the gain would then meet a decode that already clipped.
    private func addAudioOutput() -> Bool {
        let output = Self.audioReadOutput(built, gained: audioGain != nil)
        guard reader.canAdd(output) else { return false }
        reader.add(output)
        audioOutput = output
        return true
    }

    // MARK: - Running

    /// Starts the write. Main thread; `completion` is called exactly once, on
    /// the main thread, and may be called before this returns if the writer
    /// refuses to start at all.
    func start(completion: @escaping (Result<URL, any Error>) -> Void) {
        self.completion = completion
        // A cancel that arrived BEFORE this call is honoured here, before the
        // reader or the writer has started, rather than one sample later.
        lock.lock()
        let cancelledAlready = cancelRequested
        lock.unlock()
        guard !cancelledAlready else {
            report(.failure(Exporter.ExportError.cancelled))
            return
        }
        if audioInput != nil, !addAudioOutput() {
            report(.failure(Exporter.ExportError.failed(
                "The audio mix could not be read for export.")))
            return
        }
        guard writer.startWriting() else {
            report(.failure(writer.error ?? Exporter.ExportError.failed(
                "The file could not be opened for writing.")))
            return
        }
        guard reader.startReading() else {
            writer.cancelWriting()
            report(.failure(reader.error ?? Exporter.ExportError.failed(
                "The composition could not be read for export.")))
            return
        }
        // Zero, not `range.start`: the samples are rebased on the way in, so
        // the file's timeline is its own.
        writer.startSession(atSourceTime: .zero)

        let group = DispatchGroup()
        if let input = videoInput, let output = videoOutput, let encodePump {
            encodePump.run(
                sink: ExportMP4PacketSink(input: input, format: encodePump.formatDescription),
                output: output, on: videoQueue, group: group,
                isStopping: { [weak self] in self?.isStopping ?? true },
                readFailure: { [weak self] in self?.readFailure },
                fail: { [weak self] error in self?.stopped(with: error) },
                advance: { [weak self] time in self?.advance(to: time) })
        } else if let input = videoInput, let output = videoOutput {
            pump(
                input, from: output, on: videoQueue, group: group, tracksProgress: true,
                frames: frames)
        }
        if let input = audioInput, let output = audioOutput {
            // Audio drives the bar only when there is no picture to drive it,
            // and it is the only pump that can carry a gain.
            pump(
                input, from: output, on: audioQueue, group: group,
                tracksProgress: videoInput == nil, gain: audioGain, end: audioEnd)
        }
        if let input = chapterInput {
            pumpChapters(input, on: chapterQueue, group: group)
        }
        group.notify(queue: .main) { [weak self] in self?.allInputsFinished() }
    }

    /// Stops as soon as the pumps notice — within one sample. Safe from any
    /// thread and safe to call twice. It ONLY sets the flag: the reader and
    /// the writer are cancelled in `allInputsFinished`, after every pump has
    /// left its loop.
    ///
    /// **Cancelling the reader from here crashed the app** (road map 10
    /// §10.6, G3c). `reader.cancelReading()` on main while a pump was inside
    /// `copyNextSampleBuffer` tore the reader down under it: EXC_BREAKPOINT
    /// in `CMVideoFormatDescriptionMatchesImageBuffer` on the video queue, in
    /// 12 of 30 mid-export cancels of a 4K graphic project — the sheet's and
    /// the queue's Cancel path — and 16 of 40 exports stopped by a failing
    /// graphic. The cost is that a pump blocked on a slow read finishes that
    /// one sample before it stops — and a `copyNextSampleBuffer` that never
    /// returns (a pump starved because the other stopped reading) can no
    /// longer be woken by a cancel, so the completion would never fire; not
    /// seen in 70 runs, and accepted (spec §11 G-17). A cancel before `start` is refused there;
    /// `cancelReading()` before `startReading()` would raise.
    func cancel() {
        lock.lock()
        cancelRequested = true
        lock.unlock()
    }

    /// 0…1, from the last sample appended. `AVAssetWriter` has no progress of
    /// its own, so this is it.
    var progress: Double {
        lock.lock()
        defer { lock.unlock() }
        return progressValue
    }

    // MARK: - The pumps

    /// Moves one output's samples into one input until the output runs dry,
    /// the write fails, or the export is cancelled.
    ///
    /// `requestMediaDataWhenReady` re-enters this block whenever the encoder
    /// has room, so the "have I already finished?" flag lives outside it and
    /// is only ever touched on `queue`, which is serial.
    ///
    /// `gain` is nil for every pump but the audio one, and nil for the audio
    /// one too unless the export asked to be normalised — which is what
    /// keeps an ordinary export on exactly the samples it had before.
    /// `frames` is non-nil only for the video pump of a row `frameForm`
    /// names: each frame is then converted by it (`ExportFrames`).
    private func pump(
        _ input: AVAssetWriterInput, from output: AVAssetReaderOutput, on queue: DispatchQueue,
        group: DispatchGroup, tracksProgress: Bool, gain: ExportAudioGain? = nil,
        frames: ExportFrames? = nil, end: ExportAudioEnd? = nil
    ) {
        group.enter()
        var finished = false
        let stop: () -> Void = {
            guard !finished else { return }
            finished = true
            input.markAsFinished()
            group.leave()
        }
        input.requestMediaDataWhenReady(on: queue) { [weak self] in
            guard let self = self else { return }
            while input.isReadyForMoreMediaData {
                guard !finished else { return }
                guard !self.isStopping else {
                    stop()
                    return
                }
                guard let decoded = end?.isPadding == true ? nil : output.copyNextSampleBuffer()
                else {
                    // Dry for one of three reasons: the range is written, the
                    // read was cancelled (which `allInputsFinished` reports),
                    // or the read failed — and only the last is ours to name.
                    if self.reader.status == .failed {
                        self.stopped(
                            with: self.reader.error
                                ?? Exporter.ExportError.failed(
                                    "The composition could not be read to the end."))
                    } else if let end = end, !self.isStopping {
                        // Silence up to the range's end, while the input has room (#337).
                        guard let padded = end.pad(input) else { return }
                        if !padded {
                            self.stopped(with: self.writer.error
                                ?? Exporter.ExportError.failed("The file could not be written."))
                        }
                    }
                    stop()
                    return
                }
                let time = CMSampleBufferGetPresentationTimeStamp(decoded) - self.range.start
                // A sample that starts before the range does not belong to
                // this file. The reader clips to `timeRange`, so this is a
                // boundary frame, not a common case.
                guard time.isNumeric, time >= .zero else { continue }
                // An empty buffer has nothing to gain and is not malformed:
                // it is skipped, as the old Int16 kernel passed it through.
                if gain != nil, CMSampleBufferGetNumSamples(decoded) == 0 { continue }
                // The gain makes a NEW 16-bit buffer from the float one,
                // before `retimed`; with no gain the decode goes on as read.
                guard let sample = gain == nil ? decoded : gain?.apply(to: decoded) else {
                    self.stopped(
                        with: Exporter.ExportError.failed(
                            "The loudness gain could not be applied to a sample."))
                    stop()
                    return
                }
                // A `frameForm` row's frame, converted (spec §11 G-35, PR-3),
                // before `retimed`; any other goes on as read.
                guard let ready = frames == nil ? sample : frames?.convert(sample) else {
                    self.stopped(
                        with: Exporter.ExportError.failed(
                            frames?.failure ?? "A frame could not be prepared for the encoder."))
                    stop()
                    return
                }
                guard let rebased = Self.retimed(ready, by: self.range.start) else {
                    self.stopped(
                        with: Exporter.ExportError.failed(
                            "A sample could not be re-timed for the file."))
                    stop()
                    return
                }
                // A buffer past the range's end is cut or dropped (#337).
                guard let fitted = end == nil ? rebased : end?.fit(rebased) else { continue }
                guard input.append(fitted) else {
                    self.stopped(
                        with: self.writer.error
                            ?? Exporter.ExportError.failed("The file could not be written."))
                    stop()
                    return
                }
                if tracksProgress { self.advance(to: time) }
            }
        }
    }

    // MARK: - Finishing

    /// True once anything has asked the write to stop.
    var isStopping: Bool {
        lock.lock()
        defer { lock.unlock() }
        return cancelRequested || failure != nil
    }

    /// Records the first failure; later ones are noise from the other pumps
    /// unwinding. The other pumps see it before their next sample, and the
    /// read is cancelled in `allInputsFinished` (`cancel`'s doc says why).
    private func stopped(with error: any Error) {
        lock.lock()
        if failure == nil { failure = error }
        lock.unlock()
    }

    /// The reader's error once its read failed, else nil — the encoder pump's question
    /// at the end of its read, worded as `pump`'s.
    private var readFailure: (any Error)? {
        guard reader.status == .failed else { return nil }
        return reader.error
            ?? Exporter.ExportError.failed("The composition could not be read to the end.")
    }

    private func advance(to time: CMTime) {
        guard totalSeconds > 0 else { return }
        let fraction = CMTimeGetSeconds(time) / totalSeconds
        lock.lock()
        progressValue = min(max(fraction, progressValue), 1)
        lock.unlock()
    }

    /// Main thread, once every input has marked itself finished — so no pump
    /// is inside `copyNextSampleBuffer`, and the reader can be cancelled.
    private func allInputsFinished() {
        lock.lock()
        let error = failure
        let cancelled = cancelRequested
        lock.unlock()
        if error != nil || cancelled { reader.cancelReading() }
        encodePump?.close()
        if let error = error {
            writer.cancelWriting()
            report(.failure(error))
            return
        }
        if cancelled {
            // `cancelWriting` deletes the part-written file itself, which is
            // the same outcome the progress sheet arranges for a cancel.
            writer.cancelWriting()
            report(.failure(Exporter.ExportError.cancelled))
            return
        }
        writer.finishWriting { [weak self] in
            // AVFoundation calls this on a queue of its own.
            DispatchQueue.main.async { self?.writingFinished() }
        }
    }

    private func writingFinished() {
        lock.lock()
        let cancelled = cancelRequested
        lock.unlock()
        // A cancel that lands while the container is being closed still means
        // "I do not want this file": the sheet removes the destination on a
        // cancelled result, and a file the user cancelled out of is not one to
        // hand back because the timing was unlucky.
        guard !cancelled else {
            report(.failure(Exporter.ExportError.cancelled))
            return
        }
        guard writer.status == .completed else {
            report(
                .failure(
                    writer.error
                        ?? Exporter.ExportError.failed("The export stopped before it finished.")))
            return
        }
        // The `av01` brand AVAssetWriter leaves out (spec §11 CX-12 (4)).
        if encodePump != nil {
            do {
                try ExportAV1Track.brandFile(destination)
            } catch {
                report(.failure(error))
                return
            }
        }
        lock.lock()
        progressValue = 1
        lock.unlock()
        report(.success(destination))
    }

    /// The one exit, main thread, at most once.
    private func report(_ result: Result<URL, any Error>) {
        guard let completion = completion else { return }
        self.completion = nil
        completion(result)
    }
}

import AVFoundation
import os

/// The `av1_webm` row's pipeline (spec §11 CX-15): the composed movie read back exactly as
/// `ExportWriter` reads it, its picture encoded by the same `ExportEncodePump` and its sound
/// by `ExportOpusEncoder`, written into a WebM by the core (`ReelWebM`).
///
/// **A second `ExportPipeline`, and the exception to §7.8's one writer (CX-15 (2)).**
/// `AVAssetWriter` writes no WebM, so this file is the WebM half of `ExportWriter` and
/// nothing more: the same reader outputs (`ExportWriter.videoReadOutput` /
/// `audioReadOutput`), each on a reader of its own (below), the same gain (`ExportAudioGain`), the same end of the sound
/// (`ExportAudioEnd`, #337), the same chapters (`ExportChapter.partition`), the same size and
/// rates (`encodedSize`, the pump). What is its own is the container: the core interleaves,
/// clusters, cues and closes the file. **A composition with no audio track is a silent
/// movie**, as in `ExportWriter.addAudio`: no audio output, encoder or queue, and the layout
/// has no audio track.
///
/// **Two pumps.** The video pump is `ExportEncodePump` on `videoQueue` into an
/// `ExportWebMPacketSink`. The audio pump reads, checks the time, applies the gain, cuts at
/// the range (`end.fit`), encodes and adds, on `audioQueue`; once the read is dry it encodes
/// the padding silence and the encoder's tail and cuts the surplus by DiscardPadding
/// (CX-15 (5)). The sound is placed at its stamps (`ExportAudioEnd.align`), so a dropped
/// straddling buffer or a hole in the stamps keeps later sound where it was. Neither waits
/// on the file: the core queues what the interleave holds.
///
/// **One `AVAssetReader` per output (CX-15 (2), (6)).** Two outputs of ONE reader are
/// coupled: an output nobody reads stalls the reader, so a pump that stopped could leave the
/// other blocked in `copyNextSampleBuffer` for good, and `cancelReading()` cannot wake it —
/// AVFoundation forbids it concurrently with a read, and it crashed (G-17). So the video
/// composition output and the audio mix output each have their own reader over the same
/// composition (measured: the same frames byte for byte and the same sound sample for
/// sample, `webm_export_proof.py` R1), neither read waits on the other, and each pump, once it
/// has left its loop on a stop, cancels its own reader on its own queue — no thread ever
/// cancels another's (G-17's rule). A silent movie has the video reader alone.
///
/// **Cancellation, failure and progress** are `ExportWriter`'s: a flag both pumps read
/// before each read, the first failure recorded once (`stopped(with:)`, logged), progress
/// from the frames submitted. A cancelled or failed export drops the writer and removes the
/// file; a finished one is closed by `ReelWebM.finish()` off the main thread and reported on
/// main. `-RCDevWebMFault` (`ExportWebMDevFault`, dev tools only) puts a fault in either
/// pump so a proof can time the stop.
final class ExportWebMWriter: ExportPipeline, ExportAudioNormalizing {
    private let built: BuiltComposition
    private let destination: URL
    private let range: CMTimeRange
    private let totalSeconds: Double
    private let videoReader: AVAssetReader
    private let videoOutput: AVAssetReaderOutput
    /// The audio mix's own reader, nil for a silent movie; its output is added in `start`.
    private let audioReader: AVAssetReader?
    private var audioOutput: AVAssetReaderOutput?
    private let fault = ExportWebMDevFault.current()
    private let pump: ExportEncodePump
    private let opus: ExportOpusEncoder?
    private let audioEnd: ExportAudioEnd
    private let layoutJSON: String
    private var webm: ReelWebM?
    /// Written once on main between `init` and `start`, then read only on `audioQueue`.
    private var audioGain: ExportAudioGain?

    private let videoQueue = DispatchQueue(
        label: "com.kgalligan.framejob.export.webm.video", qos: .userInitiated)
    private let audioQueue = DispatchQueue(
        label: "com.kgalligan.framejob.export.webm.audio", qos: .userInitiated)

    /// Guards everything the pumps and the main thread both touch.
    private let lock = NSLock()
    private var progressValue: Double = 0
    private var cancelRequested = false
    private var failure: (any Error)?
    /// Called once, on the main thread, and then dropped.
    private var completion: ((Result<URL, any Error>) -> Void)?

    /// Builds the readers, the video output, the encoder pump, the Opus encoder when there is
    /// sound and the file's layout, or throws the `Exporter.ExportError` the sheet shows.
    /// Nothing is read or written until `start`.
    init(
        built: BuiltComposition, settings: ExportSettings, chapters: [ExportChapter], to url: URL
    ) throws {
        guard settings.writer == ExportEncodePump.writer else {
            throw Exporter.ExportError.presetUnavailable(ExportWriter.presetName(settings))
        }
        self.built = built
        destination = url
        range = Exporter.timeRange(settings, composition: built.composition)
        totalSeconds = max(0, CMTimeGetSeconds(range.duration))
        audioEnd = ExportAudioEnd(range: range)
        videoReader = try Self.reader(built.composition, range: range)
        // `ExportWriter.addVideo`'s guard: the placeholder track makes this never empty.
        guard !built.composition.tracks(withMediaType: .video).isEmpty else {
            throw Exporter.ExportError.emptyTimeline
        }
        let canvas = built.videoComposition.renderSize
        videoOutput = ExportWriter.videoReadOutput(built, settings: settings)
        guard videoReader.canAdd(videoOutput) else {
            throw Exporter.ExportError.failed("The composition could not be read for export.")
        }
        videoReader.add(videoOutput)
        pump = try ExportEncodePump(settings: settings, canvas: canvas, range: range)
        // The silent movie (CX-15 (2)): no sound, no reader, encoder or audio track.
        let hasAudio = !built.composition.tracks(withMediaType: .audio).isEmpty
        audioReader = hasAudio ? try Self.reader(built.composition, range: range) : nil
        opus = hasAudio
            ? try ExportOpusEncoder(
                bitRate: settings.audioBitrate.map { max(1, $0) }
                    ?? ExportOpusEncoder.defaultBitRate)
            : nil
        layoutJSON = try ExportWebMLayout(
            settings: settings, range: range, config: pump.config, picture: pump.picture,
            preSkip: opus?.preSkip, chapters: chapters
        ).json()
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ExportWebMWriter does not support NSCoder")
    }

    /// A reader of `composition` over `range`, for one output.
    private static func reader(_ composition: AVComposition, range: CMTimeRange) throws
        -> AVAssetReader
    {
        do {
            let reader = try AVAssetReader(asset: composition)
            reader.timeRange = range
            return reader
        } catch {
            throw Exporter.ExportError.failed(error.localizedDescription)
        }
    }

    /// `ExportWriter.normalizeAudio`'s rule: a non-finite, non-positive or unit gain is
    /// ignored, so an export that was not normalised reads the 16-bit decode.
    func normalizeAudio(byLinearGain gain: Float) {
        guard gain.isFinite, gain > 0, gain != 1 else { return }
        audioGain = ExportAudioGain(linearGain: gain)
    }

    // MARK: - Running

    /// Starts the write. Main thread; `completion` is called exactly once, on main.
    func start(completion: @escaping (Result<URL, any Error>) -> Void) {
        self.completion = completion
        guard !isStopping else { return report(.failure(Exporter.ExportError.cancelled)) }
        if let audioReader {
            let output = ExportWriter.audioReadOutput(built, gained: audioGain != nil)
            guard audioReader.canAdd(output) else {
                return report(.failure(Exporter.ExportError.failed(
                    "The audio mix could not be read for export.")))
            }
            audioReader.add(output)
            audioOutput = output
        }
        let webm: ReelWebM
        do {
            webm = try ReelWebM(path: destination.path, layoutJSON: layoutJSON)
        } catch {
            // The core creates the file before it writes the header: remove what it left.
            discard()
            return report(.failure(Exporter.ExportError.failed(
                "The WebM file could not be made: \(error.localizedDescription)")))
        }
        self.webm = webm
        guard videoReader.startReading() else {
            discard()
            return report(.failure(videoReader.error ?? Exporter.ExportError.failed(
                "The composition could not be read for export.")))
        }
        // A reader not yet started is started; the video one is (nothing reads either yet).
        if let audioReader, audioReader.status == .unknown, !audioReader.startReading() {
            videoReader.cancelReading()
            discard()
            return report(.failure(audioReader.error ?? Exporter.ExportError.failed(
                "The audio mix could not be read for export.")))
        }
        let group = DispatchGroup()
        pump.run(
            sink: ExportWebMPacketSink(webm: webm, fault: fault), output: videoOutput,
            on: videoQueue, group: group, isStopping: { [weak self] in self?.isStopping ?? true },
            readFailure: { [weak self] in self?.readFailure(of: self?.videoReader) },
            fail: { [weak self] error in self?.stopped(with: error) },
            advance: { [weak self] time in self?.advance(to: time) })
        // The video reader's own cancel, on its queue after the pump's read loop (G-17).
        group.enter()
        videoQueue.async { [self] in
            defer { group.leave() }
            if isStopping { videoReader.cancelReading() }
        }
        if let opus, let output = audioOutput, let audioReader {
            group.enter()
            audioQueue.async { [self] in
                defer { group.leave() }
                pumpAudio(output, into: webm, through: opus)
                // Its own reader, after its own last read (G-17).
                if isStopping { audioReader.cancelReading() }
            }
        }
        group.notify(queue: .main) { [weak self] in self?.allPumpsLeft() }
    }

    /// Sets the flag; both pumps see it before their next sample. Any thread, any time.
    func cancel() {
        lock.lock()
        cancelRequested = true
        lock.unlock()
    }

    var progress: Double {
        lock.lock()
        defer { lock.unlock() }
        return progressValue
    }

    // MARK: - The audio pump

    /// Reads the mix to its end, encodes it and adds each packet, holding the newest back so
    /// the last one can carry the tail's DiscardPadding (CX-15 (5)), or stops at the flag
    /// before a read.
    ///
    /// **Times are the stamps'.** Each buffer is placed at its rebased stamp
    /// (`ExportAudioEnd.align`: silence for a gap, the covered head cut), so the stream the
    /// encoder is fed is the timeline's sound frame for frame from the range's start, and
    /// packet k's first frame is the one stamped k × 960 / 48 kHz — k × 20 ms, a whole tick of
    /// WebM's 1 ms timecode scale — which is the time it is added at.
    private func pumpAudio(
        _ output: AVAssetReaderOutput, into webm: ReelWebM, through opus: ExportOpusEncoder
    ) {
        let gain = audioGain
        var held: Data?
        var added: Int64 = 0
        let packetNs = Int64(ExportOpusEncoder.framesPerPacket) * 1_000_000_000 / 48_000
        let add = { (packet: Data, padding: Int64) throws in
            try webm.add(
                track: ReelWebM.audio, ptsNs: added * packetNs, key: true,
                discardPaddingNs: padding, data: packet)
            added += 1
        }
        let feed = { (packets: [Data]) throws in
            for packet in packets {
                if let previous = held { try add(previous, 0) }
                held = packet
            }
        }
        var reads = 0
        do {
            while true {
                guard !isStopping else { return }
                reads += 1
                try fault?.beforeAudioRead(reads)
                guard let decoded = output.copyNextSampleBuffer() else {
                    if let error = readFailure(of: audioReader) {
                        stopped(with: error)
                        return
                    }
                    break
                }
                let time = CMSampleBufferGetPresentationTimeStamp(decoded) - range.start
                guard time.isNumeric, time >= .zero else { continue }
                if gain != nil, CMSampleBufferGetNumSamples(decoded) == 0 { continue }
                guard let sample = gain == nil ? decoded : gain?.apply(to: decoded) else {
                    stopped(with: Exporter.ExportError.failed(
                        "The loudness gain could not be applied to a sample."))
                    return
                }
                let frame = CMTimeConvertScale(
                    time, timescale: CMTimeScale(ExportAudioEnd.sampleRate),
                    method: .roundHalfAwayFromZero
                ).value
                for placed in audioEnd.align(sample, at: Int(frame)) {
                    guard let fitted = audioEnd.fit(placed) else { continue }
                    try feed(try opus.encode(fitted))
                }
            }
            for silence in audioEnd.padding() {
                try feed(try opus.encode(silence))
            }
            var tail = (held.map { [$0] } ?? []) + (try opus.finish())
            // The decoded length is packets × 960 − pre-skip; the surplus over #337's
            // target is cut whole packets first, then by the last one's DiscardPadding.
            var padding = (Int(added) + tail.count) * ExportOpusEncoder.framesPerPacket
                - opus.preSkip - audioEnd.target
            while padding >= ExportOpusEncoder.framesPerPacket, !tail.isEmpty {
                tail.removeLast()
                padding -= ExportOpusEncoder.framesPerPacket
            }
            guard padding >= 0, padding < ExportOpusEncoder.framesPerPacket else {
                stopped(with: Exporter.ExportError.failed(
                    "The audio could not be encoded to its exact length."))
                return
            }
            let paddingNs = (Int64(padding) * 1_000_000_000 + 24_000) / 48_000
            for (index, packet) in tail.enumerated() {
                try add(packet, index == tail.count - 1 ? paddingNs : 0)
            }
            try webm.endTrack(ReelWebM.audio)
        } catch {
            stopped(with: error)
        }
    }

    // MARK: - Finishing

    private var isStopping: Bool {
        lock.lock()
        defer { lock.unlock() }
        return cancelRequested || failure != nil
    }

    private func stopped(with error: any Error) {
        lock.lock()
        let first = failure == nil
        if first { failure = error }
        lock.unlock()
        // The unified log (not stdout or the proofs' log), so a stop names its cause.
        let which = first ? "first" : "later"
        let why = error.localizedDescription
        Self.log.error(
            "WebM export stopped (\(which, privacy: .public)): \(why, privacy: .public)")
    }

    private static let log = Logger(subsystem: "com.kgalligan.FrameJob", category: "export.webm")

    private func readFailure(of reader: AVAssetReader?) -> (any Error)? {
        guard let reader, reader.status == .failed else { return nil }
        return reader.error
            ?? Exporter.ExportError.failed("The composition could not be read to the end.")
    }

    private func advance(to time: CMTime) {
        guard totalSeconds > 0 else { return }
        let fraction = CMTimeGetSeconds(time) / totalSeconds
        lock.lock()
        progressValue = min(max(fraction, progressValue), 1)
        lock.unlock()
    }

    /// Main thread, once both pumps have left (each reader already cancelled by its own
    /// pump on a stop): the encoder closed, then the file finished off main or dropped and
    /// removed.
    private func allPumpsLeft() {
        lock.lock()
        let error = failure
        let cancelled = cancelRequested
        lock.unlock()
        if fault != nil {
            let shared = audioReader === videoReader ? " (one reader)" : ""
            ExportWebMDevFault.log(
                "readers: video \(videoReader.status.rawValue), audio "
                    + (audioReader.map { "\($0.status.rawValue)" } ?? "none") + shared)
        }
        pump.close()
        if let error { return finishFailed(error) }
        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
        guard let webm else { return finishFailed(Exporter.ExportError.cancelled) }
        videoQueue.async { [weak self] in
            let closed: (any Error)?
            do {
                try webm.finish()
                closed = nil
            } catch {
                closed = Exporter.ExportError.failed(
                    "The WebM file could not be finished: \(error.localizedDescription)")
            }
            DispatchQueue.main.async { self?.fileClosed(closed) }
        }
    }

    private func fileClosed(_ error: (any Error)?) {
        lock.lock()
        let cancelled = cancelRequested
        lock.unlock()
        if let error { return finishFailed(error) }
        // A cancel while the file was being closed still means "I do not want this file".
        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
        lock.lock()
        progressValue = 1
        lock.unlock()
        report(.success(destination))
    }

    private func finishFailed(_ error: any Error) {
        discard()
        report(.failure(error))
    }

    /// Drops the writer and removes the part-written file.
    private func discard() {
        webm = nil
        try? FileManager.default.removeItem(at: destination)
    }

    /// The one exit, main thread, at most once.
    private func report(_ result: Result<URL, any Error>) {
        guard let completion else { return }
        self.completion = nil
        completion(result)
    }
}

