71	func pixels(_ buffer: CVPixelBuffer) -> Data {
72	    CVPixelBufferLockBaseAddress(buffer, .readOnly)
73	    defer { CVPixelBufferUnlockBaseAddress(buffer, .readOnly) }
74	    guard let base = CVPixelBufferGetBaseAddress(buffer) else { return Data() }
75	    let row = CVPixelBufferGetWidth(buffer) * 8
76	    let stride = CVPixelBufferGetBytesPerRow(buffer)
77	    var out = Data(capacity: row * CVPixelBufferGetHeight(buffer))
78	    for y in 0..<CVPixelBufferGetHeight(buffer) {
79	        out.append(Data(bytes: base + y * stride, count: row))
80	    }
81	    return out
82	}
