84	func planes(_ frame: I010Frame) -> Data {
85	    let words = frame.buffer.contents().assumingMemoryBound(to: UInt16.self)
86	    var out = Data()
87	    for y in 0..<frame.height {
88	        out.append(Data(bytes: words + y * frame.lumaStride, count: frame.width * 2))
89	    }
90	    for offset in [frame.cbOffset, frame.crOffset] {
91	        for y in 0..<(frame.height + 1) / 2 {
92	            out.append(Data(
93	                bytes: words + offset + y * frame.chromaStride, count: (frame.width + 1) / 2 * 2))
94	        }
95	    }
96	    return out
97	}
